import re
from collections import Counter


def parse_triples(text):
    """Parse triples with or without quotes around their values."""
    triples = []

    for match in re.finditer(r"\(([^()]*)\)", text):
        parts = [part.strip().strip("'\"") for part in match.group(1).split(",")]

        if len(parts) != 3:
            raise ValueError(f"Invalid triple: {match.group(0)}")

        triples.append(tuple(parts))

    return triples


def normalize_predicate(predicate, known_predicates):
    """Replace a normalized predicate with its matching base predicate."""
    matches = [
        p for p in known_predicates
        if predicate.startswith(p)
    ]

    # Prefer the longest matching predicate if prefixes overlap.
    return max(matches, key=len) if matches else predicate


def compare_triples(first_text, second_text):
    first = parse_triples(first_text)
    second = parse_triples(second_text)

    known_predicates = {triple[1] for triple in first}

    normalized_second = [
        (
            subject,
            normalize_predicate(predicate, known_predicates),
            obj,
        )
        for subject, predicate, obj in second
    ]

    first_counter = Counter(first)
    second_counter = Counter(normalized_second)

    only_first = first_counter - second_counter
    only_second = second_counter - first_counter

    print("=== Triples only in the first list ===")
    if only_first:
        for triple, count in sorted(only_first.items()):
            print(f"{triple} (count: {count})")
    else:
        print("None")

    print("\n=== Triples only in the second list ===")
    if only_second:
        for triple, count in sorted(only_second.items()):
            print(f"{triple} (count: {count})")
    else:
        print("None")

    print("\n=== Summary ===")
    print(f"Triples in first list: {len(first)}")
    print(f"Triples in second list: {len(second)}")
    print(f"Equivalent triples: {sum((first_counter & second_counter).values())}")
    print(f"Extra occurrences in first list: {sum(only_first.values())}")
    print(f"Extra occurrences in second list: {sum(only_second.values())}")


